mapper.insert:

	    SELECT
	        'IVRV'||
	        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(INTERVIEW_REVIEW_NO), LENGTH('IVRV' ) + 1)), 0) + 1, 6, '0')
	    FROM INTERVIEW_REVIEW


  INSERT INTO INTERVIEW_REVIEW (
		INTERVIEW_REVIEW_NO
			, INTERVIEW_NO
			, COM_ID
			, JOB_CODE
			, INTERVIEW_DATE
			, INTERVIEW_REVIEW_DATE
			, USER_ID
		) VALUES (
		#{interviewReviewNo}
			, #{interviewNo}
			, #{comId}
			, #{jobCode}
			, #{interviewDate}
			, SYSDATE
			, #{userId}
	)
